// DAC drive index — record JAH-GPCS-DACAMP-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"snr_db": 120, "power_mw": 1000, "price_usd": 200};
var value = (m.snr_db*m.power_mw/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-DACAMP-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-DACAMP-000001|' + value.toFixed(2) + ' drive index');

